        'ศุกร์': { trait: ['รักสวยงาม มีเสน่ห์ รักศิลปะ', 'loves beauty, charming, artistic'], car: ['ศิลปะ บันเทิง ความงาม แฟชั่น', 'art, entertainment, beauty, fashion'], day: ['วันศุกร์', 'Friday'], color: ['ฟ้า', 'sky-blue'] },
