    if (v >= Q[Q.length - 1][0])
        return Q[Q.length - 1][1];
    let lo = 0, hi = Q.length - 1;
    while (lo < hi) {
        const m = (lo + hi) >> 1;
        if (Q[m][0] < v)
            lo = m + 1;
        else
            hi = m;
    }
    if (Q[lo][0] === v)
        return Q[lo][1];
